using Microsoft.AspNetCore.Mvc; using LuminosHrm.Models; using LuminosHrm.Services;
namespace LuminosHrm.Controllers;
public class EmployeeController(IEmployeeService service) : Controller { public IActionResult Index(string? search,string? department){var list=service.GetAll().Where(e=>(string.IsNullOrWhiteSpace(search)||e.FullName.Contains(search,StringComparison.OrdinalIgnoreCase)||e.Email.Contains(search,StringComparison.OrdinalIgnoreCase))&&(string.IsNullOrWhiteSpace(department)||department=="All departments"||e.Dept==department)).ToList();return View(new EmployeeDirectoryViewModel{Employees=list,Search=search??"",Department=department??"All departments"});} public IActionResult Create()=>View(new Employee()); [HttpPost][ValidateAntiForgeryToken] public IActionResult Create(Employee e){if(!ModelState.IsValid)return View(e);service.Add(e);TempData["Toast"]="Employee added successfully";return RedirectToAction(nameof(Index));} public IActionResult Details(int id)=>PartialView("_EmployeeDrawer",service.Get(id)); }
